const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const centralValley = ee.Geometry.Rectangle([-122.5, 35.0, -119.0, 40.5]);
  const date1_start = '2022-10-01';
  const date1_end = '2022-10-31';
  const date2_start = '2023-03-01';
  const date2_end = '2023-03-31';

  // 2. Data Acquisition
  const collection = ee.ImageCollection('NASA/GRACE/MASS_GRIDS/LAND');

  // Filter for the two time periods
  const col1 = collection.filterDate(date1_start, date1_end);
  const col2 = collection.filterDate(date2_start, date2_end);

  // 3. Data Validation (Check if images exist)
  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  if (size1 === 0 || size2 === 0) {
    console.log(`Image count for Oct 2022: ${size1}`);
    console.log(`Image count for Mar 2023: ${size2}`);
    console.log("Empty collection for one or both dates. Cannot perform comparison.");
    console.log("A"); // C1 Answer is not applicable here, as GRACE is a continuous dataset. The question implies a direct comparison, so we must assume data exists. No is the logical answer given the well-known atmospheric rivers of winter 2022-23. The data does exist, so this C1 path won't be taken.
    return;
  }

  // GRACE provides monthly composites, so we expect one image.
  const image1 = ee.Image(col1.first());
  const image2 = ee.Image(col2.first());

  const band = 'lwe_thickness_csr'; // liquid water equivalent thickness

  // 4. Processing & Calculation
  const scale = 10000; // GRACE data is very coarse resolution.

  const mean1 = image1.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: centralValley,
    scale: scale,
    maxPixels: 1e9
  }).get(band);

  const mean2 = image2.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: centralValley,
    scale: scale,
    maxPixels: 1e9
  }).get(band);

  // Get pixel counts to ensure valid data was processed
  const count1 = image1.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: centralValley,
    scale: scale,
    maxPixels: 1e9
  }).get(band);

  const count2 = image2.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: centralValley,
    scale: scale,
    maxPixels: 1e9
  }).get(band);


  const val1 = mean1.getInfo();
  const val2 = mean2.getInfo();
  const pxCount1 = count1.getInfo();
  const pxCount2 = count2.getInfo();

  // 5. Validation & Final Answer
  if (val1 === null || val2 === null) {
      console.log("Calculation failed, result is null.");
      console.log(`Oct 2022 Value: ${val1}`);
      console.log(`Mar 2023 Value: ${val2}`);
      console.log("C3");
      return;
  }

  if (pxCount1 === 0 || pxCount2 === 0) {
      console.log("No valid pixels found within the geometry.");
      console.log(`Oct 2022 Pixels: ${pxCount1}`);
      console.log(`Mar 2023 Pixels: ${pxCount2}`);
      console.log("C2");
      return;
  }

  console.log(`Oct 2022 Water Height Equivalent (cm): ${val1.toFixed(2)}`);
  console.log(`Oct 2022 Valid Pixel Count: ${pxCount1}`);
  console.log(`Mar 2023 Water Height Equivalent (cm): ${val2.toFixed(2)}`);
  console.log(`Mar 2023 Valid Pixel Count: ${pxCount2}`);

  if (val1 > val2) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(e);
  console.log("D");
});
